@namespace sv_44e32a9fa18d4ce1a2c98ad154e077e0.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge @PriorityClass">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>

    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move-left" @onclick="OnMoveLeftClick">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move-right" @onclick="OnMoveRightClick">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };

    private async Task OnMoveLeftClick() => await OnMoveLeft.InvokeAsync();
    private async Task OnMoveRightClick() => await OnMoveRight.InvokeAsync();
}

@namespace sv_44e32a9fa18d4ce1a2c98ad154e077e0.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="Save" disabled="@isSaving">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter]
    public EventCallback<TaskItem> OnTaskCreated { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today;
    private bool isSaving;

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        isSaving = true;
        try
        {
            await OnTaskCreated.InvokeAsync(
                new TaskItem(0, title, assignee, priority, dueDate, ""));
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@namespace sv_44e32a9fa18d4ce1a2c98ad154e077e0.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="() => OnMoveTask.InvokeAsync((task.Id, -1))"
                      OnMoveRight="() => OnMoveTask.InvokeAsync((task.Id, 1))" />
        }
    </div>

    @if (showForm)
    {
        <AddTaskForm OnTaskCreated="HandleTaskCreated" OnCancel="() => showForm = false" />
    }
    else
    {
        <button class="btn-add-task" @onclick="() => showForm = true">Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string Title { get; set; } = "";

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback<(int TaskId, int Direction)> OnMoveTask { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnAddTask { get; set; }

    private bool showForm;

    private async Task HandleTaskCreated(TaskItem formData)
    {
        await OnAddTask.InvokeAsync(formData);
        showForm = false;
    }
}

