@page "/board"
@namespace sv_44e32a9fa18d4ce1a2c98ad154e077e0.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error-message">@errorMessage</p>
}
else
{
    <BoardStats TotalCount="allTasks.Count"
                ToDoCount="ToDoTasks.Count"
                InProgressCount="InProgressTasks.Count"
                DoneCount="DoneTasks.Count"
                OverdueCount="OverdueCount" />

    <div class="search-bar">
        <input type="text" placeholder="Search tasks..." @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="kanban-board">
        <KanbanColumn Title="To Do"
                      Tasks="FilteredToDo"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="(formData) => HandleAddTask(formData, \"To Do\")" />

        <KanbanColumn Title="In Progress"
                      Tasks="FilteredInProgress"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="(formData) => HandleAddTask(formData, \"In Progress\")" />

        <KanbanColumn Title="Done"
                      Tasks="FilteredDone"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="(formData) => HandleAddTask(formData, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    private List<TaskItem> ToDoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => allTasks.Where(t => t.Status == "Done").ToList();

    private List<TaskItem> FilteredToDo => ApplySearch(ToDoTasks);
    private List<TaskItem> FilteredInProgress => ApplySearch(InProgressTasks);
    private List<TaskItem> FilteredDone => ApplySearch(DoneTasks);

    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);

    private List<TaskItem> ApplySearch(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;

        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleMoveTask((int TaskId, int Direction) move)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == move.TaskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        var newIndex = currentIndex + move.Direction;
        if (newIndex < 0 || newIndex >= Statuses.Length) return;

        var newStatus = Statuses[newIndex];
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            allTasks = allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask(TaskItem formData, string status)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(
                formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
            allTasks.Add(created with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat {
    font-weight: 600;
}

.stat-overdue {
    color: #dc3545;
}

.search-bar {
    margin-bottom: 1rem;
}

.search-bar input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 1rem;
}

.kanban-board {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 1rem;
    align-items: start;
}

.loading-message,
.error-message {
    padding: 1rem;
}

.error-message {
    color: #dc3545;
}

::deep .kanban-column {
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-height: 300px;
    display: flex;
    flex-direction: column;
}

::deep .column-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1.1rem;
}

::deep .column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

::deep .task-title {
    margin: 0 0 0.25rem 0;
    font-size: 0.95rem;
}

::deep .task-assignee {
    margin: 0 0 0.5rem 0;
    font-size: 0.85rem;
    color: #6c757d;
}

::deep .priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

::deep .priority-high {
    background: #dc3545;
    color: #fff;
}

::deep .priority-medium {
    background: #ffc107;
    color: #212529;
}

::deep .priority-low {
    background: #28a745;
    color: #fff;
}

::deep .task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

::deep .task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

::deep .btn-move-left,
::deep .btn-move-right {
    padding: 0.25rem 0.5rem;
    font-size: 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

::deep .btn-move-left:hover,
::deep .btn-move-right:hover {
    background: #e9ecef;
}

::deep .btn-add-task {
    margin-top: 0.75rem;
    padding: 0.5rem;
    width: 100%;
    border: 1px dashed #adb5bd;
    border-radius: 6px;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
}

::deep .btn-add-task:hover {
    background: #e9ecef;
}

::deep .add-task-form {
    margin-top: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .add-task-form input,
::deep .add-task-form select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.9rem;
}

::deep .form-actions {
    display: flex;
    gap: 0.5rem;
}

::deep .btn-save {
    padding: 0.4rem 0.8rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-save:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-cancel {
    padding: 0.4rem 0.8rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

